sp_widget.client_script:
api.controller = function($window, spModal) {

  /* =========================================================
     GATENOW · AWARD DETAIL · Client script

     Reading is local. The three writes go to the server and
     then reload, which is the one time a repaint is the right
     thing to do — the reload brings back the recorded response,
     the new journal entry, the recounted tiles and the redrawn
     charts in one pass.

     Both decisions confirm first, and the confirm carries an
     optional note. Declining releases the money to someone else
     and cannot be undone; accepting commits to a reporting
     schedule. Neither should happen on a mis-click, and a
     decline with a reason on it is worth far more to the
     program office than a bare state change.

     Nothing here calculates chart geometry. The server ships
     finished coordinates and this binds them, so there is one
     place to look when a line is in the wrong spot.
     ========================================================= */

  var c = this;

  c.busy = '';
  c.note = '';
  c.tab  = 'overview';


  /* =====================================================
     TABS

     Filtered here rather than with ng-if on the repeat: two
     directives on one element each make a child scope, and
     that pair is not worth debugging.

     A tab with nothing behind it is not shown at all. An empty
     tab is a dead end the reader has to open to find out
     about.
     ===================================================== */

  function buildTabs() {

    if (!c.data.found) return [];

    var all = [
      { key: 'overview', label: c.data.t.tabOverview,
        show : function() { return true; },
        count: function() { return 0; } },

      { key: 'letter', label: c.data.t.tabLetter,
        show : function() { return !!c.data.award.letter; },
        count: function() { return 0; } },

      { key: 'program', label: c.data.t.tabProgram,
        show : function() { return !!c.data.program; },
        count: function() { return 0; } },

      { key: 'applicant', label: c.data.t.tabApp,
        show : function() { return !!c.data.application; },
        count: function() { return 0; } },

      { key: 'claims', label: c.data.t.tabClaims,
        show : function() { return (c.data.claims || []).length > 0; },
        count: function() { return (c.data.claims || []).length; } },

      { key: 'notes', label: c.data.t.tabNotes,
        show : function() { return true; },
        count: function() { return (c.data.notes || []).length; } }
    ];

    return all.filter(function(t) { return t.show(); });
  }

  c.tabs = buildTabs();

  c.setTab = function(key) {
    if (!key || c.tab === key) return;
    for (var i = 0; i < c.tabs.length; i++) {
      if (c.tabs[i].key === key) {
        c.tab = key;
        return;
      }
    }
  };

  c.isTab = function(key) { return c.tab === key; };


  /* =====================================================
     WRITES
     ===================================================== */

  function tell(title, message) {
    spModal.open({
      title: title,
      message: message || '',
      buttons: [{ label: c.data.t.ok, primary: true }]
    });
  }

  function send(payload, okTitle) {
    c.busy = payload.action;

    c.server.get(payload).then(function(r) {
      c.busy = '';
      var resp = (r && r.data) ? r.data : {};

      if (resp.success) {
        c.note = '';
        tell(okTitle, c.data.award.program);
        c.server.update().then(function() {
          c.tabs = buildTabs();
        });
      } else {
        tell(c.data.t.failed, resp.error);
      }
    }, function() {
      c.busy = '';
      tell(c.data.t.failed, '');
    });
  }

  /* the confirm carries a free-text field, and whatever is
     typed into it is written onto the award as a work note
     alongside the decision */
  function confirmThen(title, message, yes, action, okTitle) {

    spModal.open({
      title  : title,
      message: message,
      input  : true,
      label  : c.data.t.reasonLabel,
      value  : '',
      buttons: [
        { label: c.data.t.keep, cancel: true },
        { label: yes, primary: true }
      ]
    }).then(function(result) {

      var reason = '';
      if (result && typeof result === 'object') reason = result.value || '';
      else if (typeof result === 'string')      reason = result;

      send({ action: action, reason: reason }, okTitle);
    });
  }

  c.accept = function() {
    if (c.busy || !c.data.award.canAct) return;
    confirmThen(c.data.t.acceptTitle, c.data.t.acceptText,
                c.data.t.acceptYes, 'acknowledge', c.data.t.accepted);
  };

  c.decline = function() {
    if (c.busy || !c.data.award.canAct) return;
    confirmThen(c.data.t.declineTitle, c.data.t.declineText,
                c.data.t.declineYes, 'decline', c.data.t.declined);
  };

  c.sendNote = function() {
    if (c.busy) return;

    var body = (c.note || '').trim();
    if (!body) return;

    send({ action: 'add_note', note: body }, c.data.t.noteSent);
  };

};

sp_widget.css:
/* =========================================================
   GATENOW · AWARD DETAIL
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   The token block, the shell, the header, the tiles, the card,
   the state chips and the buttons are lifted verbatim from My
   Awards. Nothing was retuned, because the two pages are one
   page as far as the reader is concerned and a detail view
   that is half a shade off reads as a different product.

   TYPE — identical to My Awards
     tile      30  700  tabular   headline figures
     title     26  700  -0.03em   page title
     program   19  600  -0.018em  award heading
     figure    24  700  tabular   the amount
     body      15  400            supporting copy
     data      14  600  tabular   dates
     label     11  600   0.14em   uppercase small caps

   ONE ADDITION over the list
   Charts. They introduce no new colour: claimed is the accent
   blue, paid is the same green already used where money has
   moved, and the award ceiling is a dashed navy line, because
   a limit is not a series and should not look like one.
   ========================================================= */

/* ---------- overflow overrides ----------
   Service Portal wraps every widget in a panel that clips
   anything leaving its box, which cuts off the sidebar tooltips.
   Same block as the dashboard and My Awards, so all three
   behave identically.
   ------------------------------------------------------- */

.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout { overflow: visible !important; }

.aw-sidebar {
  flex: 0 0 auto;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 10; /* Ensures sidebar tooltips stay above the scrolling dashboard */
  overflow: visible; /* Kept visible to prevent tooltip clipping as noted in your comments */
}



/* ---------- typeface ---------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$a-navy:   #0a2540;
$a-ink-2:  rgba(10, 37, 64, 0.72);
$a-ink-3:  rgba(10, 37, 64, 0.54);
$a-ink-4:  rgba(10, 37, 64, 0.38);
$a-line:   rgba(10, 37, 64, 0.10);
$a-line-2: rgba(10, 37, 64, 0.06);
$a-tint:   rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$a-blue:    #1560e0;
$a-blue-dk: #0f4cbb;
$a-blue-1:  rgba(21, 96, 224, 0.08);
$a-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- state ---------- */
$a-soon:   #0d7d8c;
$a-good:   #1f8a63;
$a-good-1: rgba(31, 138, 99, 0.10);
$a-warn:   #a4741f;
$a-warn-1: rgba(164, 116, 31, 0.10);
$a-warn-2: rgba(164, 116, 31, 0.26);

/* the one destructive colour, used only on decline */
$a-stop:   #b8394a;
$a-stop-1: rgba(184, 57, 74, 0.08);
$a-stop-2: rgba(184, 57, 74, 0.28);

$a-white: #ffffff;
$a-page:  #f4f6fb;
$a-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$a-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

.gn-layout {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  background: $a-page;
  font-family: $a-font;
}

/* Without min-width: 0 a flex child refuses to shrink below its
   own content width, and slides under the rail rather than
   narrowing. That is the usual cause of a stubborn overlap once
   the widths are right. */
.gaw {
  flex: 1;
  min-width: 0;
  overflow: visible;
}

.gaw {
  min-height: 100vh;
  padding: 30px 38px 72px;
  background: $a-page;
  font-family: $a-font;
  color: $a-navy;
  -webkit-font-smoothing: antialiased;
}

.gaw *,
.gaw *::before,
.gaw *::after { box-sizing: border-box; }


/* =========================================================
   HEADER

   Same bar as My Awards, with the back link taking the place
   of the search box. The title carries the award number rather
   than the word "Award" on its own, because the reader arrived
   here from a list of them.
   ========================================================= */

.gaw-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  margin-bottom: 26px;
}

.gaw-top__left {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.gaw .gaw-top__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: $a-navy;
}

.gaw-top__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.gaw-back {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  gap: 9px;
  height: 30px;
  padding: 0 11px 0 7px;
  border-radius: 9px;
  background: transparent;
  color: $a-ink-3;
  font-size: 13.5px;
  font-weight: 500;
  text-decoration: none;
  transition: background 0.4s $a-ease, color 0.4s $a-ease;
}

.gaw-back:hover,
.gaw-back:focus {
  background: rgba(255, 255, 255, 0.7);
  color: $a-navy;
  text-decoration: none;
}

.gaw-back__arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid $a-line;
  transition: transform 0.4s $a-ease, border-color 0.4s $a-ease;
}

.gaw-back:hover .gaw-back__arrow {
  transform: translateX(-3px);
  border-color: $a-blue-2;
}

.gaw-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: #1560e0;
  color: $a-white;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.03em;
  flex-shrink: 0;
}


/* =========================================================
   NOT AVAILABLE
   ========================================================= */

.gaw-blank {
  max-width: 520px;
  margin: 70px auto;
  padding: 52px 34px 46px;
  border: 1px solid $a-line;
  border-radius: 18px;
  background: $a-white;
  text-align: center;
}

.gaw-blank__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: $a-blue-1;
  color: $a-blue;
  font-size: 22px;
}

.gaw .gaw-blank__title {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $a-navy;
}

.gaw .gaw-blank__text {
  max-width: 44ch;
  margin: 11px auto 24px;
  font-size: 15px;
  line-height: 1.64;
  color: $a-ink-3;
}


/* =========================================================
   THE HERO

   The list card, opened out. Same rail, same state chip, same
   figure block on the right, so the row the reader clicked and
   the page they land on are visibly the same object.
   ========================================================= */

.gaw-card {
  position: relative;
  padding: 22px 26px 20px 28px;
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.gaw-hero { margin-bottom: 24px; }

/* the rail states where the award stands without another badge */
.gaw-card__rail {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
}

.gaw-card--pending .gaw-card__rail  { background: $a-warn; }
.gaw-card--active .gaw-card__rail   { background: $a-blue; }
.gaw-card--done .gaw-card__rail     { background: $a-good; }
.gaw-card--declined .gaw-card__rail { background: rgba(10, 37, 64, 0.16); }

/* an award waiting on a decision is the only thing here with a
   cost attached to ignoring it, so it is the only one tinted */
.gaw-card--pending { background: linear-gradient(180deg, rgba(164, 116, 31, 0.04) 0%, $a-white 42%); }

.gaw-card__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 26px;
  align-items: start;
  padding-bottom: 18px;
  margin-bottom: 16px;
  border-bottom: 1px solid $a-line-2;
}

.gaw-card__lead { min-width: 0; }

.gaw-card__top {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 10px;
}

.gaw-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.gaw-state__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gaw-state--pending  { color: $a-warn; }
.gaw-state--active   { color: $a-blue-dk; }
.gaw-state--done     { color: $a-good; }
.gaw-state--declined { color: $a-ink-4; }

.gaw-state--pending .gaw-state__dot  { background: $a-warn; }
.gaw-state--active .gaw-state__dot   { background: $a-blue; }
.gaw-state--done .gaw-state__dot     { background: $a-good; }
.gaw-state--declined .gaw-state__dot {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px rgba(10, 37, 64, 0.28);
}

.gaw-card__meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw-card__sep { color: rgba(10, 37, 64, 0.22); }

.gaw-wait {
  padding: 3px 9px;
  border: 1px solid $a-warn-2;
  border-radius: 6px;
  background: $a-warn-1;
  color: $a-warn;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

/* the one place the detail page departs from the list: the
   program name is the subject of this page rather than one row
   among ten, so it takes the page-title size */
.gaw .gaw-hero__program {
  margin: 0;
  max-width: 34ch;
  font-size: 26px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.03em;
  color: $a-navy;
}

.gaw .gaw-card__title {
  max-width: 68ch;
  margin: 8px 0 0;
  font-size: 15px;
  line-height: 1.55;
  color: $a-ink-2;
}

.gaw .gaw-card__hint {
  margin: 8px 0 0;
  font-size: 13.5px;
  color: $a-ink-4;
}

.gaw-card--declined .gaw-hero__program { color: $a-ink-3; }


/* ---------- the amount ---------- */

.gaw-card__figure {
  text-align: right;
  min-width: 0;
}

.gaw-figure__label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw-figure__value {
  display: block;
  margin-top: 8px;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gaw-figure__note {
  display: block;
  margin-top: 7px;
  font-size: 11.5px;
  line-height: 1.5;
  color: $a-ink-4;
}


/* ---------- foot ---------- */

.gaw-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
}

.gaw .gaw-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 30px;
  margin: 0;
  padding: 0;
}

.gaw-fact {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.gaw .gaw-fact dt {
  margin: 0;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw .gaw-fact dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.008em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gaw-acts {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

/* what stands where the two buttons stood, once the decision
   has been made */
.gaw-done {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 9px 14px;
  border: 1px solid $a-line;
  border-radius: 10px;
  background: $a-tint;
}

.gaw-done__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 50%;
  font-size: 12px;
}

.gaw-card--active .gaw-done__mark {
  background: $a-good-1;
  color: $a-good;
}

.gaw-card--declined .gaw-done__mark {
  background: rgba(10, 37, 64, 0.06);
  color: $a-ink-3;
}

.gaw-done__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.gaw-done__title {
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: $a-navy;
}

.gaw-done__note {
  font-size: 11.5px;
  color: $a-ink-4;
}


/* =========================================================
   TILES
   ========================================================= */

.gaw-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.gaw-tile {
  position: relative;
  padding: 20px 22px 22px;
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: transform 0.5s $a-ease, box-shadow 0.5s $a-ease;
}

.gaw-tile:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px rgba(10, 37, 64, 0.08);
}

.gaw-tile__rule {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: $a-blue-2;
  transform-origin: left center;
}

.gaw-tile.is-alert .gaw-tile__rule { background: $a-warn-2; }

.gaw .gaw-tile__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw .gaw-tile__value {
  margin: 12px 0 0;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.034em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

/* the response tile carries words rather than a figure, so it
   sizes down to sit level with the numbers beside it */
.gaw-tile--pending .gaw-tile__value {
  font-size: 22px;
  letter-spacing: -0.026em;
}

.gaw .gaw-tile__note {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
  color: $a-ink-3;
}

.gaw-tile.is-alert .gaw-tile__note {
  color: $a-warn;
  font-weight: 500;
}


/* =========================================================
   PANELS
   ========================================================= */

.gaw-panel {
  padding: 22px 24px 24px;
  margin-bottom: 24px;
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.gaw-panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 22px;
  margin-bottom: 24px;
}

.gaw .gaw-panel__title {
  margin: 0;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: $a-navy;
}

.gaw .gaw-panel__hint {
  margin: 6px 0 0;
  max-width: 66ch;
  font-size: 13.5px;
  line-height: 1.55;
  color: $a-ink-4;
}

.gaw .gaw-panel__hint--tight { margin: 0 0 18px; }

.gaw .gaw-panel__empty {
  margin: 0;
  padding: 24px 0 6px;
  font-size: 14px;
  color: $a-ink-4;
}

.gaw-chip {
  padding: 6px 12px;
  border-radius: 999px;
  background: $a-tint;
  font-size: 12.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $a-ink-3;
  white-space: nowrap;
}

.gaw-chip--open    { background: $a-blue-1;  color: $a-blue-dk; }
.gaw-chip--closing { background: $a-warn-1;  color: $a-warn; }
.gaw-chip--over    { background: $a-stop-1;  color: $a-stop; }


/* =========================================================
   THE AWARD WINDOW

   Two dates, one track, and today marked at its real position.
   An award with three weeks left is a different thing from one
   with eleven months left, and two dates on their own do not
   say which without the reader doing the arithmetic.
   ========================================================= */

.gaw-win { padding-top: 6px; }

.gaw-win__track {
  position: relative;
  display: block;
  height: 10px;
  border-radius: 999px;
  background: $a-tint;
  box-shadow: inset 0 0 0 1px $a-line-2;
}

.gaw-win__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: rgba(21, 96, 224, 0.5);
  transform-origin: left center;
}

.gaw-win__now {
  position: absolute;
  top: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: translate(-50%, -50%);
}

.gaw-win__pin {
  width: 3px;
  height: 22px;
  border-radius: 2px;
  background: $a-navy;
  box-shadow: 0 0 0 3px $a-white;
}

.gaw-win__today {
  position: absolute;
  top: 20px;
  padding: 3px 8px;
  border-radius: 6px;
  background: $a-navy;
  color: $a-white;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
}

.gaw-win__ends {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-top: 34px;
}

.gaw-win__end {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.gaw-win__end--right { text-align: right; }

.gaw-win__label {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw-win__date {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}


/* ---------- the pace line ----------

   One sentence rather than a panel of its own: time elapsed
   set against money drawn. Both percentages are already on the
   page; the comparison between them is the thing nobody makes
   on their own, and it does not need a chart to say.
   ----------------------------------------------------------- */

.gaw .gaw-pace {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin: 22px 0 0;
  padding-top: 16px;
  border-top: 1px solid $a-line-2;
  font-size: 13.5px;
  line-height: 1.6;
  color: $a-ink-3;
}

.gaw-pace__mark {
  width: 7px;
  height: 7px;
  margin-top: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gaw-pace__mark--open    { background: $a-good; }
.gaw-pace__mark--closing { background: $a-warn; }
.gaw-pace__mark--over    { background: $a-stop; }


/* =========================================================
   THE RECORD
   ========================================================= */

.gaw-block {
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

/* the same pill tabs as My Awards, sat on a tinted strip so
   they read as the head of the card rather than as free
   buttons floating on white */
.gaw-tabs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.gaw-tabs--record {
  padding: 12px 16px;
  border-bottom: 1px solid $a-line-2;
  background: rgba(10, 37, 64, 0.02);
  flex-wrap: nowrap;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.gaw-tab {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: $a-ink-2;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  flex-shrink: 0;
  cursor: pointer;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease, color 0.4s $a-ease;
}

.gaw-tab:hover {
  background: rgba(255, 255, 255, 0.7);
  color: $a-navy;
}

.gaw-tab.is-on {
  background: $a-white;
  border-color: $a-line;
  color: $a-navy;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.05);
}

.gaw-tab__count {
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-4;
}

.gaw-block__body { padding: 24px 26px 30px; }

.gaw .gaw-sub {
  margin: 0 0 16px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-blue;
}

.gaw .gaw-sub + .gaw-kvs + .gaw-sub {
  margin-top: 30px;
  padding-top: 26px;
  border-top: 1px solid $a-line-2;
}

.gaw .gaw-kvs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px 34px;
  margin: 0;
  padding: 0;
}

.gaw-kv { min-width: 0; }

.gaw .gaw-kv dt {
  margin: 0 0 5px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw .gaw-kv dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: -0.008em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
  word-break: break-word;
}

/* said rather than left blank, so nobody wonders whether it
   failed to load */
.gaw .gaw-kv dd.is-blank {
  font-weight: 400;
  font-style: italic;
  font-variant-numeric: normal;
  color: $a-ink-4;
}

.gaw-prose { margin-top: 26px; }

.gaw .gaw-prose__label {
  margin: 0 0 7px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

/* the line breaks the author typed are kept */
.gaw .gaw-prose__text {
  margin: 0;
  max-width: 76ch;
  font-size: 15px;
  line-height: 1.7;
  color: $a-ink-2;
  white-space: pre-line;
}

.gaw .gaw-empty {
  margin: 0;
  padding: 48px 0;
  text-align: center;
  font-size: 14.5px;
  color: $a-ink-4;
}


/* =========================================================
   THE AWARD LETTER

   Set as a letter rather than as a field value, because that
   is what it is. Wider leading, a measure that stops at 68
   characters, and a rule under it carrying the reference.
   ========================================================= */

.gaw-letter {
  max-width: 72ch;
  padding: 30px 34px 26px;
  border: 1px solid $a-line;
  border-radius: 14px;
  background: linear-gradient(180deg, $a-tint 0%, $a-white 120px);
}

.gaw .gaw-letter__text {
  margin: 0;
  max-width: 68ch;
  font-size: 15.5px;
  line-height: 1.85;
  color: $a-ink-2;
  white-space: pre-line;
}

.gaw .gaw-letter__foot {
  margin: 26px 0 0;
  padding-top: 16px;
  border-top: 1px solid $a-line-2;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}


/* =========================================================
   CLAIMS TABLE

   A table only where the data is genuinely tabular. Four
   columns, no rules between rows, the amount right-aligned and
   tabular so the digits line up down the column.
   ========================================================= */

.gaw-rows {
  display: grid;
  gap: 2px;
}

.gaw-rows__head {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr) minmax(0, 1fr) 120px;
  align-items: center;
  gap: 16px;
  padding: 0 14px 10px;
  border-bottom: 1px solid $a-line-2;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw-rows__row {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr) minmax(0, 1fr) 120px;
  align-items: center;
  gap: 16px;
  padding: 14px;
  border-radius: 10px;
  transition: background 0.4s $a-ease;
}

.gaw-rows__row:hover { background: $a-tint; }

.gaw-rows__num { text-align: right; }

.gaw-rows__ref {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gaw-rows__when {
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-3;
}

.gaw-rows__amount {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gaw-pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.gaw-pill--paid      { background: $a-good-1; color: $a-good; }
.gaw-pill--approved  { background: $a-blue-1; color: $a-blue-dk; }
.gaw-pill--submitted { background: $a-tint;   color: $a-ink-2; }
.gaw-pill--rejected  { background: $a-stop-1; color: $a-stop; }
.gaw-pill--other     { background: $a-tint;   color: $a-ink-3; }


/* =========================================================
   WORK NOTES

   The box sits above the thread rather than below it, so it is
   not at the bottom of a long history.
   ========================================================= */

.gaw-write {
  padding: 16px;
  margin-bottom: 24px;
  border: 1px solid $a-line;
  border-radius: 13px;
  background: $a-tint;
}

.gaw-write textarea {
  width: 100%;
  padding: 12px 14px;
  border: 1px solid $a-line;
  border-radius: 10px;
  background: $a-white;
  font-family: inherit;
  font-size: 15px;
  line-height: 1.65;
  color: $a-navy;
  resize: vertical;
  transition: border-color 0.4s $a-ease, box-shadow 0.4s $a-ease;
}

.gaw-write textarea:focus {
  outline: 0;
  border-color: rgba(21, 96, 224, 0.45);
  box-shadow: 0 0 0 3px $a-blue-1;
}

.gaw-write textarea::placeholder { color: $a-ink-4; }

.gaw-write__foot {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}

.gaw .gaw-locked {
  margin: 0 0 24px;
  padding: 14px 16px;
  border: 1px solid $a-line;
  border-radius: 11px;
  background: $a-tint;
  font-size: 13.5px;
  color: $a-ink-3;
}

.gaw .gaw-thread {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gaw .gaw-thread li {
  padding: 14px 16px 15px;
  border: 1px solid $a-line;
  border-left: 3px solid $a-line;
  border-radius: 0 12px 12px 0;
  background: $a-white;
}

/* the applicant's own notes sit on the accent side of the
   thread, which is what makes it read as a conversation rather
   than as a log */
.gaw .gaw-thread li.is-mine {
  border-left-color: $a-blue;
  background: $a-blue-1;
}

.gaw-thread__who {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 8px;
}

.gaw-thread__name {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.008em;
  color: $a-navy;
}

.gaw-thread__when {
  font-size: 11.5px;
  color: $a-ink-4;
  white-space: nowrap;
}

.gaw .gaw-thread__body {
  margin: 0;
  max-width: 74ch;
  font-size: 14.5px;
  line-height: 1.68;
  color: $a-ink-2;
  white-space: pre-line;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.gaw-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 17px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease, color 0.4s $a-ease;
}

.gaw-btn--primary {
  background: $a-blue;
  border-color: $a-blue;
  color: $a-white;
}

.gaw-btn--primary:hover,
.gaw-btn--primary:focus {
  background: $a-blue-dk;
  border-color: $a-blue-dk;
  color: $a-white;
  text-decoration: none;
}

/* Declining cannot be undone, so it does not look like every
   other button on the page. It is not filled either, because a
   solid red next to a solid blue is a coin toss at speed. */
.gaw-btn--danger {
  border-color: $a-stop-2;
  color: $a-stop;
}

.gaw-btn--danger:hover,
.gaw-btn--danger:focus {
  background: $a-stop-1;
  border-color: $a-stop;
  color: $a-stop;
  text-decoration: none;
}

.gaw-btn--ghost {
  border-color: $a-line;
  color: $a-ink-2;
}

.gaw-btn--ghost:hover,
.gaw-btn--ghost:focus {
  border-color: $a-blue-2;
  color: $a-blue-dk;
  text-decoration: none;
}

.gaw-btn--quiet { color: $a-ink-3; }

.gaw-btn--quiet:hover,
.gaw-btn--quiet:focus {
  color: $a-navy;
  text-decoration: none;
}

.gaw-btn:disabled {
  opacity: 0.5;
  cursor: default;
}

.gaw-btn:focus-visible,
.gaw-tab:focus-visible,
.gaw-back:focus-visible {
  outline: 2px solid $a-blue;
  outline-offset: 2px;
}


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gawRise {
    from { opacity: 0; transform: translateY(14px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gawDrawX {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
  }

  @keyframes gawPin {
    from { opacity: 0; transform: translate(-50%, -50%) scaleY(0.3); }
    to   { opacity: 1; transform: translate(-50%, -50%) scaleY(1); }
  }

  .gaw-top  { animation: gawRise 0.6s $a-ease backwards; }
  .gaw-hero { animation: gawRise 0.6s $a-ease 0.06s backwards; }
  .gaw-blank { animation: gawRise 0.6s $a-ease 0.08s backwards; }

  .gaw-tile { animation: gawRise 0.62s $a-ease backwards; }

  .gaw-tile--value   { animation-delay: 0.12s; }
  .gaw-tile--pending { animation-delay: 0.18s; }
  .gaw-tile--active  { animation-delay: 0.24s; }
  .gaw-tile--done    { animation-delay: 0.30s; }

  .gaw-tile__rule { animation: gawDrawX 0.7s $a-ease 0.34s backwards; }

  .gaw-panel { animation: gawRise 0.6s $a-ease 0.3s backwards; }
  .gaw-block { animation: gawRise 0.6s $a-ease 0.44s backwards; }

  .gaw-win__fill { animation: gawDrawX 0.85s $a-ease 0.4s backwards; }
  .gaw-win__now  { animation: gawPin 0.5s $a-ease 0.72s backwards; }

  .gaw .gaw-thread li { animation: gawRise 0.45s $a-ease backwards; }
  .gaw-rows__row      { animation: gawRise 0.4s $a-ease backwards; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1200px) {

  .gaw { padding: 26px 24px 64px; }

  .gaw-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }

}

@media (max-width: 900px) {

  .gaw { padding: 22px 16px 56px; }

  .gaw .gaw-top__title { font-size: 22px; }

  .gaw-tiles { grid-template-columns: minmax(0, 1fr); }

  /* the amount moves under the heading rather than being
     squeezed into a column too narrow to hold it */
  .gaw-card__head {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }

  .gaw .gaw-hero__program {
    font-size: 22px;
    max-width: none;
  }

  .gaw-card__figure {
    text-align: left;
    padding-top: 14px;
    border-top: 1px solid $a-line-2;
  }

  .gaw-card__foot {
    align-items: flex-start;
    flex-direction: column;
  }

  .gaw-acts { width: 100%; }

  .gaw-btn { flex: 1; }

  .gaw-done { width: 100%; }

  .gaw .gaw-kvs { grid-template-columns: minmax(0, 1fr); }

  .gaw-block__body { padding: 20px 16px 26px; }

  .gaw-letter { padding: 22px 20px 20px; }

  /* the claims table stops being a table and becomes a stack,
     because four columns at 320px is four columns of nothing */
  .gaw-rows__head { display: none; }

  .gaw-rows__row {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 6px 12px;
    padding: 14px;
    border: 1px solid $a-line;
    border-radius: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gaw * { transition: none; }
  .gaw-tile:hover { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · AWARD DETAIL
     Service Portal widget · Server script
     ========================================================= */

  var APPLICANT = 'x_enno_gatenow_service_applicants';
  var AWARD     = 'x_enno_gatenow_grant_awards';
  var PROGRAM   = 'x_enno_gatenow_grant_program';
  var PROJECT   = 'x_enno_gatenow_project';
  var CLAIM     = 'x_enno_gatenow_reimbursement';

  var me = gs.getUserID();

  data.success = false;
  data.error   = '';
  data.saved   = '';

  if (typeof input === 'undefined' || input === null) input = {};

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  function param(key, dflt) {
    try {
      if (input && input[key] !== undefined && input[key] !== null) return input[key];
    } catch (e) { /* fall through */ }
    return dflt;
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase().trim();
  }

  function toGDT(value) {
    if (!value) return null;
    var s = '' + value;
    if (s.length === 10) s += ' 00:00:00';
    try { return new GlideDateTime(s); } catch (e) { return null; }
  }

  function fmtDate(value) {
    var g = toGDT(value);
    if (!g) return '';
    try { return g.getDate().getByFormat('d MMM yyyy'); } catch (e) { return '' + value; }
  }

  function fmtWhen(value) {
    var g = toGDT(value);
    if (!g) return '';
    try {
      return g.getDate().getByFormat('d MMM yyyy') + ', ' +
             g.getDisplayValue().split(' ')[1].substring(0, 5);
    } catch (e) { return fmtDate(value); }
  }

  function daysUntil(value) {
    var g = toGDT(value);
    if (!g) return null;
    return Math.round((g.getNumericValue() - new GlideDateTime().getNumericValue()) / 86400000);
  }

  function num(raw) {
    if (raw === null || raw === undefined || raw === '') return 0;
    var s = '' + raw;
    if (s.indexOf(';') !== -1) s = s.split(';').pop();
    var n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }

  function commas(n) {
    var s = '' + Math.round(n);
    var out = '';
    var c = 0;
    for (var i = s.length - 1; i >= 0; i--) {
      out = s.charAt(i) + out;
      c++;
      if (c % 3 === 0 && i > 0) out = ',' + out;
    }
    return out;
  }

  function fmtFull(n)  { return n > 0 ? '$' + commas(n) : '$0'; }

  function fmtShort(n) {
    if (!n) return '$0';
    if (n >= 1000000) return '$' + (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1000)    return '$' + Math.round(n / 1000) + 'K';
    return '$' + commas(n);
  }

  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }

  function pickDisplay(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getDisplayValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }

  function text(raw) {
    if (!raw) return '';
    return ('' + raw)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<\/div>/gi, '\n')
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/[ \t]+/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  /* ============================================================
     CHROME
     ============================================================ */

  data.sideBar = $sp.getWidget(opt('sidebar_widget', 'sidebar'));

  var u = gs.getUser();
  var fn = u.getFirstName() || '';
  var ln = u.getLastName() || '';
  data.userInitials = (fn.charAt(0) + ln.charAt(0)).toUpperCase() ||
                      (u.getDisplayName() || 'U').substring(0, 2).toUpperCase();

  data.pages = {
    awards  : opt('awards_page', 'awards'),
    project : opt('project_page', 'x_enno_gatenow_project_detail'),
    programs: opt('programs_page', 'x_enno_gatenow_programs')
  };

  /* ============================================================
     WHICH AWARD, AND MAY THEY SEE IT
     ============================================================ */

  function resolveId() {
    var found = '';
    function consider(value) {
      if (found) return;
      if (value === null || value === undefined) return;
      var v = ('' + value).trim();
      if (v.length === 32) found = v;
    }
    try { consider(options.sys_id); }   catch (e) {}
    try { consider(options.award_id); } catch (e) {}
    try {
      if (typeof input !== 'undefined' && input) {
        consider(input.sys_id);
        consider(input.award_id);
      }
    } catch (e) {}
    consider($sp.getParameter('sys_id'));
    consider($sp.getParameter('award_id'));
    return found;
  }

  var awardId = resolveId();
  data.found = false;
  var aw = new GlideRecordSecure(AWARD);
  var applicantId = '';

  if (!awardId) {
    data.error = gs.getMessage('No award was passed to this page.');
    gs.warn('[AwardDetail] no award id on options, input or the URL');
  } else {

    // 1. Gather all applications owned by the logged-in user
    var myApplicantIds = [];
    var appGr = new GlideRecordSecure(APPLICANT);
    appGr.addQuery('user', me);
    appGr.query();
    while (appGr.next()) {
      myApplicantIds.push(appGr.getUniqueValue());
    }

    // 2. Query the award forcing the applicant to be in the user's list
    aw.addQuery('sys_id', awardId);
    if (myApplicantIds.length > 0) {
      aw.addQuery('applicant', 'IN', myApplicantIds.join(','));
    } else {
      aw.addQuery('applicant', 'NO_MATCH'); 
    }
    aw.setLimit(1);
    aw.query();

    if (aw.next()) {
      data.found = true;
      applicantId = aw.getValue('applicant');
    } else {
      // Fallback existence check for correct error messaging
      var probe = new GlideRecordSecure(AWARD);
      var exists = false;
      try { if (probe.get(awardId)) exists = true; } catch (e) {}

      data.error = exists
        ? gs.getMessage('That award is not linked to one of your applications.')
        : gs.getMessage('That award no longer exists.');

      gs.warn('[AwardDetail] ' + me + ' attempted to open ' + awardId + ' (Exists: ' + exists + ')');
    }
  }

  if (!data.found) {
    data.t = {
      missing: gs.getMessage('Award not available'),
      back   : gs.getMessage('Back to my awards')
    };
    return;
  }

  /* ============================================================
     WRITE ACTIONS
     ============================================================ */

  var action = String(param('action', ''));

  function journalField(gr) {
    try { if (gr.isValidField('work_notes')) return 'work_notes'; } catch (e) {}
    try { if (gr.isValidField('comments'))   return 'comments'; } catch (e) {}
    return '';
  }

  function writeNote(gr, body) {
    if (!body) return false;
    var f = journalField(gr);
    if (!f) {
      gs.info('[AwardDetail] no journal field on ' + AWARD);
      return false;
    }
    try {
      gr[f] = body;
      return true;
    } catch (e) {
      gs.info('[AwardDetail] journal not writable: ' + e.message);
      return false;
    }
  }

  function decide(toState, okState) {
    var current = lower(aw.getValue('applicant_response'));

    if (current !== 'pending') {
      data.error = gs.getMessage('This award is no longer waiting on you. Refresh to see where it stands.');
      return;
    }

    aw.setValue('applicant_response', toState);
    var reason = ('' + param('reason', '')).trim();

    writeNote(aw, (okState === 'acknowledged'
      ? gs.getMessage('Award accepted by the applicant.')
      : gs.getMessage('Award declined by the applicant.')) +
      (reason ? '\n\n' + reason : ''));

    if (aw.update()) {
      if (applicantId) {
        try {
          var app = new GlideRecordSecure(APPLICANT);
          // Changed .get() to .addQuery() to safely update the application state
          app.addQuery('sys_id', applicantId);
          app.addQuery('user', me);
          app.setLimit(1);
          app.query();
          if (app.next()) {
            app.setValue('state', okState === 'acknowledged' ? 'award_acknowledged' : 'declined_by_applicant');
            app.update();
          }
        } catch (e) {
          gs.error('[AwardDetail] application state not updated: ' + e.message);
        }
      }

      data.success = true;
      data.saved   = okState;

      if (aw.get(awardId)) {
        // refreshed
      }

    } else {
      data.error = gs.getMessage('The decision did not save. Nothing has changed, try again.');
    }
  }

  if (action === 'acknowledge') decide('acknowledged', 'acknowledged');
  if (action === 'decline')     decide('rejected', 'rejected');

  if (action === 'add_note') {
    var note = ('' + param('note', '')).trim();
    if (!note) {
      data.error = gs.getMessage('There was nothing to send.');
    } else if (!writeNote(aw, note)) {
      data.error = gs.getMessage('This award has no work notes field to write to.');
    } else if (aw.update()) {
      data.success = true;
      data.saved = 'note';
      if (aw.get(awardId)) { }
    } else {
      data.error = gs.getMessage('The message did not send. Try again.');
    }
  }

  /* ============================================================
     THE AWARD
     ============================================================ */

  var STATE_MAP = {
    pending: {
      key  : 'pending',
      label: gs.getMessage('Waiting on you'),
      hint : gs.getMessage('Accept or decline to move this forward')
    },
    acknowledged: {
      key  : 'active',
      label: gs.getMessage('Accepted'),
      hint : gs.getMessage('The project opens once the program team sets it up')
    },
    rejected: {
      key  : 'declined',
      label: gs.getMessage('Declined'),
      hint : gs.getMessage('You turned this award down')
    }
  };

  var rawState = lower(aw.getValue('applicant_response'));
  var meta = STATE_MAP[rawState] || {
    key  : 'pending',
    label: aw.getDisplayValue('applicant_response') || gs.getMessage('Waiting on you'),
    hint : gs.getMessage('Accept or decline to move this forward')
  };

  var amount   = num(aw.getValue('build_grant_amount'));
  var startRaw = aw.getValue('award_start_date');
  var endRaw   = aw.getValue('award_end_date');

  data.award = {
    sysId : aw.getUniqueValue(),
    number: aw.getValue('number'),
    program  : aw.getDisplayValue('program_name'),
    category : aw.getDisplayValue('grant_program'),
    programId: aw.getValue('grant_program'),
    state      : meta.key,
    stateLabel : meta.label,
    stateHint  : meta.hint,
    rawState   : rawState,
    canAct     : (rawState === 'pending'),
    value     : amount,
    valueText : fmtFull(amount),
    valueShort: fmtShort(amount),
    opportunity: pick(aw, ['funding_opportunity_number']),
    fain       : pick(aw, ['fain']),
    listing    : pick(aw, ['assistance_listing']),
    procurement: pick(aw, ['procurement_request_number']),
    startDate    : fmtDate(startRaw),
    effectiveDate: fmtDate(pick(aw, ['effective_date_of_award'])),
    federalDate  : fmtDate(pick(aw, ['federal_award_date'])),
    endDate      : fmtDate(endRaw),
    decisionReason: text(pick(aw, ['decision_reason'])),
    letter        : text(pick(aw, ['award_letter'])),
    created: fmtWhen(aw.getValue('sys_created_on')),
    moved  : fmtWhen(aw.getValue('sys_updated_on'))
  };

  data.award.waitingDays = (rawState === 'pending')
    ? Math.abs(daysUntil(aw.getValue('sys_created_on')) || 0)
    : null;

  /* ---------- the award window ---------- */

  data.window = null;
  if (startRaw && endRaw) {
    var span = daysUntil(endRaw) - daysUntil(startRaw);
    var left = daysUntil(endRaw);
    if (span && span > 0) {
      var gone = 0 - daysUntil(startRaw);
      var pct  = Math.max(0, Math.min(100, Math.round((gone / span) * 100)));
      var tone, note;
      if (left < 0) {
        tone = 'over';
        note = Math.abs(left) + ' ' + (Math.abs(left) === 1 ? gs.getMessage('day past the end date') : gs.getMessage('days past the end date'));
      } else if (left <= 30) {
        tone = 'closing';
        note = left + ' ' + (left === 1 ? gs.getMessage('day left') : gs.getMessage('days left'));
      } else {
        tone = 'open';
        note = left + ' ' + gs.getMessage('days left');
      }
      data.window = { pct: pct, days: span, left: left, tone: tone, note: note };
    }
  }

  /* ============================================================
     THE PROJECT AND ITS CLAIMS
     ============================================================ */

  data.project = null;
  var projectIds = [];

  try {
    var pj = new GlideRecordSecure(PROJECT);
    pj.addQuery('x_enno_gatenow_applicant', applicantId);
    pj.query();
    while (pj.next()) {
      projectIds.push(pj.getUniqueValue());
      if (!data.project) {
        data.project = {
          sysId: pj.getUniqueValue(),
          name : pj.getValue('project_name') || pj.getValue('number'),
          number: pj.getValue('number'),
          state: pickDisplay(pj, ['state', 'status'])
        };
      }
    }
  } catch (e) {
    gs.info('[AwardDetail] project unreadable: ' + e.message);
  }

  var claimRows = [];
  var CLAIM_DATES  = ['submitted_date', 'submission_date', 'claim_date', 'request_date', 'sys_created_on'];
  var CLAIM_AMOUNT = ['amount_requested', 'amount', 'requested_amount'];

  function statusKey(display) {
    var s = lower(display);
    if (s.indexOf('paid') !== -1)   return 'paid';
    if (s.indexOf('reject') !== -1 || s.indexOf('denied') !== -1) return 'rejected';
    if (s.indexOf('approv') !== -1) return 'approved';
    if (s.indexOf('submit') !== -1 || s.indexOf('review') !== -1 || s.indexOf('pending') !== -1) return 'submitted';
    return 'other';
  }

  if (projectIds.length) {
    try {
      var cl = new GlideRecordSecure(CLAIM);
      cl.addQuery('project', 'IN', projectIds.join(','));
      cl.orderBy('sys_created_on');
      cl.query();
      while (cl.next()) {
        var stDisplay = pickDisplay(cl, ['status', 'state']) || gs.getMessage('Unknown');
        var whenRaw   = pick(cl, CLAIM_DATES) || cl.getValue('sys_created_on');
        var amt       = num(pick(cl, CLAIM_AMOUNT));
        claimRows.push({
          sysId : cl.getUniqueValue(),
          number: cl.getValue('number') || cl.getUniqueValue().substring(0, 8),
          status: stDisplay,
          key   : statusKey(stDisplay),
          raw   : whenRaw,
          date  : fmtDate(whenRaw),
          amount: amt,
          amountText: fmtFull(amt)
        });
      }
    } catch (e) {
      gs.info('[AwardDetail] claims unreadable: ' + e.message);
    }
  }

  data.claims = claimRows.slice().reverse();

  /* ---------- what has been drawn down ---------- */

  var claimedTotal = 0;
  var paidTotal    = 0;
  var liveClaims   = 0;

  for (var ci = 0; ci < claimRows.length; ci++) {
    if (claimRows[ci].key === 'rejected') continue;
    claimedTotal += claimRows[ci].amount;
    liveClaims++;
    if (claimRows[ci].key === 'paid') paidTotal += claimRows[ci].amount;
  }

  data.draw = null;
  if (amount > 0 && claimRows.length) {
    data.draw = {
      awardText  : fmtShort(amount),
      claimed    : claimedTotal,
      claimedText: fmtShort(claimedTotal),
      claimedFull: fmtFull(claimedTotal),
      paid       : paidTotal,
      paidText   : fmtShort(paidTotal),
      paidFull   : fmtFull(paidTotal),
      claims     : liveClaims,
      remainingText: fmtShort(Math.max(0, amount - claimedTotal)),
      claimedPct : Math.min(100, Math.round((claimedTotal / amount) * 100)),
      paidPct    : Math.min(100, Math.round((paidTotal / amount) * 100)),
      over       : claimedTotal > amount
    };
  }

  /* ============================================================
     THE PROGRAM AND THE APPLICATION
     ============================================================ */

  data.program = null;
  var progMin = 0;
  var progMax = 0;

  if (data.award.programId) {
    try {
      var pg = new GlideRecordSecure(PROGRAM);
      if (pg.get(data.award.programId)) {
        progMin = num(pick(pg, ['min_award']));
        progMax = num(pick(pg, ['max_award']));
        data.program = {
          number  : pg.getValue('number'),
          name    : pick(pg, ['program_name']) || pg.getDisplayValue('number'),
          category: pg.getDisplayValue('category'),
          manager : pg.getDisplayValue('program_manager'),
          agency  : pickDisplay(pg, ['agency', 'department', 'awarding_agency']),
          state   : pickDisplay(pg, ['state', 'status']),
          synopsis: text(pick(pg, ['synopsis', 'program_description'])),
          eligibility: text(pick(pg, ['eligibility', 'eligibility_criteria'])),
          terms   : text(pick(pg, ['terms_and_conditions'])),
          minAward: fmtFull(progMin),
          maxAward: fmtFull(progMax),
          totalFunding: (function () {
            var tf = num(pick(pg, ['program_budget', 'total_funding', 'total_program_funding', 'funding_amount']));
            return tf ? fmtFull(tf) : '';
          })(),
          openDate : fmtDate(pick(pg, ['open_date', 'opening_date', 'start_date'])),
          closeDate: fmtDate(pick(pg, ['close_date', 'closing_date', 'end_date']))
        };
      }
    } catch (e) {
      gs.info('[AwardDetail] program unreadable: ' + e.message);
    }
  }

  data.application = null;
  var requestedNum = 0;

  try {
    var ap = new GlideRecordSecure(APPLICANT);
    if (ap.get(applicantId)) {
      requestedNum = num(pick(ap, ['requested_budget']));
      var addressBits = [
        pick(ap, ['street', 'address', 'address_line_1']),
        pick(ap, ['city']),
        pickDisplay(ap, ['state_province', 'province']),
        pick(ap, ['zip', 'postal_code', 'zip_code']),
        pickDisplay(ap, ['country'])
      ];
      data.application = {
        number   : ap.getValue('number'),
        title    : pick(ap, ['proposal_title', 'short_description']),
        summary  : text(pick(ap, ['proposal_summary', 'project_summary', 'description'])),
        requested: requestedNum ? fmtFull(requestedNum) : '',
        submitted: fmtDate(ap.getValue('submission_date')),
        decided  : fmtDate(pick(ap, ['decision_date', 'reviewed_date'])),
        state    : ap.getDisplayValue('state'),
        organisation: pick(ap, ['organization']),
        orgType  : pickDisplay(ap, ['organization_type', 'org_type', 'entity_type']),
        ein      : pick(ap, ['ein', 'tax_id', 'duns', 'uei']),
        contact  : [pick(ap, ['first_name']), pick(ap, ['last_name'])].filter(function (x) { return !!x; }).join(' '),
        email    : pick(ap, ['email']),
        phone    : pick(ap, ['phone_number']),
        website  : pick(ap, ['website', 'web_site', 'url']),
        address  : addressBits.filter(function (x) { return !!x; }).join(', ')
      };
    }
  } catch (e) {
    gs.info('[AwardDetail] application unreadable: ' + e.message);
  }

  /* ============================================================
     WORK NOTES
     ============================================================ */

  data.notes = [];

  try {
    var jr = new GlideRecordSecure('sys_journal_field');
    jr.addQuery('element_id', awardId);
    jr.addQuery('element', 'IN', 'work_notes,comments');
    jr.orderByDesc('sys_created_on');
    jr.setLimit(80);
    jr.query();

    while (jr.next()) {
      var byId    = jr.getValue('sys_created_by');
      var whenRaw2 = jr.getValue('sys_created_on');
      data.notes.push({
        sysId: jr.getUniqueValue(),
        body : ('' + jr.getValue('value')).trim(),
        by   : byId,
        mine : (byId === gs.getUserName()),
        when : fmtWhen(whenRaw2),
        ago  : (function () {
                 var d = daysUntil(whenRaw2);
                 if (d === null) return '';
                 var days = Math.abs(d);
                 if (days === 0) return gs.getMessage('today');
                 if (days === 1) return gs.getMessage('yesterday');
                 return days + ' ' + gs.getMessage('days ago');
               })()
      });
    }
  } catch (e) {
    gs.info('[AwardDetail] journal unreadable: ' + e.message);
  }

  data.canWriteNotes = true;
  try {
    data.canWriteNotes = !!journalField(aw) && aw.canWrite();
  } catch (e) { }

  /* ============================================================
     TILES
     ============================================================ */

  data.tiles = [
    {
      key  : 'value',
      label: gs.getMessage('Award amount'),
      value: fmtShort(amount),
      note : data.application && data.application.requested
               ? data.application.requested + ' ' + gs.getMessage('requested')
               : gs.getMessage('as set on the award record')
    },
    {
      key  : 'pending',
      label: gs.getMessage('Your response'),
      value: meta.label,
      note : rawState === 'pending'
               ? (data.award.waitingDays > 0
                    ? gs.getMessage('waiting') + ' ' + data.award.waitingDays + ' ' + gs.getMessage('days')
                    : gs.getMessage('nothing sent yet'))
               : gs.getMessage('recorded') + ' ' + data.award.moved,
      alert: rawState === 'pending'
    },
    {
      key  : 'active',
      label: gs.getMessage('Award window'),
      value: data.window ? data.window.pct + '%' : '—',
      note : data.window ? data.window.note : gs.getMessage('no start and end date set')
    },
    {
      key  : 'done',
      label: gs.getMessage('Drawn down'),
      value: data.draw ? data.draw.claimedText : '—',
      note : data.draw
               ? data.draw.paidText + ' ' + gs.getMessage('paid across') + ' ' +
                 data.draw.claims + ' ' + (data.draw.claims === 1 ? gs.getMessage('claim') : gs.getMessage('claims'))
               : (rawState === 'acknowledged' ? gs.getMessage('nothing claimed yet')
                                              : gs.getMessage('claims open once accepted'))
    }
  ];

  /* ============================================================
     PACE
     ============================================================ */

  data.pace = { show: false, tone: 'open', note: '' };

  if (data.window && rawState === 'acknowledged' && amount > 0) {
    var elapsed = data.window.pct;
    var drawn   = Math.round(Math.min(100, (claimedTotal / amount) * 100));
    var gap     = drawn - elapsed;

    if (gap >= 12) {
      data.pace = {
        show: true, tone: 'closing',
        note: drawn + '% ' + gs.getMessage('of the award has been claimed against') + ' ' +
              elapsed + '% ' + gs.getMessage('of the award period. At this rate the funds run out before the end date.')
      };
    } else if (gap <= -12) {
      data.pace = {
        show: true, tone: 'over',
        note: elapsed + '% ' + gs.getMessage('of the award period has passed and') + ' ' +
              drawn + '% ' + gs.getMessage('of the award has been claimed. Unclaimed funds are usually returned at the end date.')
      };
    } else {
      data.pace = {
        show: true, tone: 'open',
        note: drawn + '% ' + gs.getMessage('claimed against') + ' ' + elapsed + '% ' +
              gs.getMessage('of the award period elapsed.')
      };
    }
  }

  /* ============================================================
     COPY
     ============================================================ */

  data.t = {
    title  : opt('label_title', gs.getMessage('Award')),
    back   : gs.getMessage('Back to my awards'),
    missing: gs.getMessage('Award not available'),
    accept     : gs.getMessage('Accept award'),
    decline    : gs.getMessage('Decline'),
    viewProject: gs.getMessage('Open project'),
    acceptTitle : gs.getMessage('Accept this award?'),
    acceptText  : gs.getMessage('Accepting starts the project and commits you to the reporting schedule attached to this program.'),
    acceptYes   : gs.getMessage('Yes, accept it'),
    declineTitle: gs.getMessage('Decline this award?'),
    declineText : gs.getMessage('This cannot be undone. The funding will be released to another applicant.'),
    declineYes  : gs.getMessage('Yes, decline it'),
    keep        : gs.getMessage('Go back'),
    reasonLabel: gs.getMessage('Add a note for the program office'),
    reasonHint : gs.getMessage('Optional. Whatever you write goes onto the award record as a work note.'),
    answered: gs.getMessage('Your response is recorded'),
    accepted: gs.getMessage('Award accepted'),
    declined: gs.getMessage('Award declined'),
    noteSent: gs.getMessage('Work note added'),
    failed  : gs.getMessage('That did not work'),
    ok      : gs.getMessage('OK'),
    waitingFor: gs.getMessage('Waiting'),
    days      : gs.getMessage('days'),
    day       : gs.getMessage('day'),
    awarded   : gs.getMessage('Awarded'),
    tabOverview: gs.getMessage('Overview'),
    tabLetter  : gs.getMessage('Award letter'),
    tabProgram : gs.getMessage('Program'),
    tabApp     : gs.getMessage('Applicant'),
    tabClaims  : gs.getMessage('Claims'),
    tabNotes   : gs.getMessage('Work notes'),
    windowTitle: gs.getMessage('The award window'),
    windowHint : gs.getMessage('From the start date to the end date, with today marked'),
    windowNone : gs.getMessage('Set a start and an end date on the award and this fills in.'),
    windowStart: gs.getMessage('Starts'),
    windowEnd  : gs.getMessage('Ends'),
    today      : gs.getMessage('Today'),
    claimedLbl: gs.getMessage('Claimed'),
    paidLbl   : gs.getMessage('Paid'),
    money      : gs.getMessage('The money'),
    awardAmount: gs.getMessage('Award amount'),
    dates      : gs.getMessage('Key dates'),
    awardStart : gs.getMessage('Award start'),
    effective  : gs.getMessage('Effective date'),
    federal    : gs.getMessage('Federal award date'),
    awardEnd   : gs.getMessage('Award end'),
    created    : gs.getMessage('Award raised'),
    lastUpdated: gs.getMessage('Last change'),
    ids        : gs.getMessage('Reference numbers'),
    reference  : gs.getMessage('Award number'),
    opportunity: gs.getMessage('Funding opportunity number'),
    fain       : gs.getMessage('FAIN'),
    listing    : gs.getMessage('Assistance listing'),
    procurement: gs.getMessage('Procurement request number'),
    decision  : gs.getMessage('Decision reason'),
    letterNone: gs.getMessage('No award letter has been attached to this award.'),
    progIdent  : gs.getMessage('The program'),
    progName   : gs.getMessage('Program'),
    progNumber : gs.getMessage('Program number'),
    progCat    : gs.getMessage('Category'),
    progManager: gs.getMessage('Program manager'),
    progAgency : gs.getMessage('Awarding agency'),
    progState  : gs.getMessage('Program status'),
    progRange  : gs.getMessage('Award range'),
    progTotal  : gs.getMessage('Total program funding'),
    progOpen   : gs.getMessage('Opens'),
    progClose  : gs.getMessage('Closes'),
    progSynopsis: gs.getMessage('About the program'),
    progEligibility: gs.getMessage('Eligibility'),
    progTerms  : gs.getMessage('Terms and conditions'),
    progNone   : gs.getMessage('The program record could not be read.'),
    appSub      : gs.getMessage('The application'),
    applicantSub: gs.getMessage('The applicant'),
    appNumber   : gs.getMessage('Application'),
    appTitle    : gs.getMessage('Proposal title'),
    appSummary  : gs.getMessage('Proposal summary'),
    appRequested: gs.getMessage('You requested'),
    appAwarded  : gs.getMessage('You were awarded'),
    appSubmitted: gs.getMessage('Submitted'),
    appDecided  : gs.getMessage('Decision made'),
    appState    : gs.getMessage('Current state'),
    appOrg      : gs.getMessage('Organisation'),
    appOrgType  : gs.getMessage('Organisation type'),
    appEin      : gs.getMessage('Tax or entity ID'),
    appContact  : gs.getMessage('Contact'),
    appEmail    : gs.getMessage('Email'),
    appPhone    : gs.getMessage('Phone'),
    appAddress  : gs.getMessage('Address'),
    appWebsite  : gs.getMessage('Website'),
    appNone     : gs.getMessage('The application record could not be read.'),
    project    : gs.getMessage('Project'),
    claimsHint : gs.getMessage('Every reimbursement claim raised against the project attached to this award.'),
    claimsNone : gs.getMessage('No claims have been raised against this award yet.'),
    claimRef   : gs.getMessage('Claim'),
    claimDate  : gs.getMessage('Raised'),
    claimStatus: gs.getMessage('Status'),
    claimAmount: gs.getMessage('Amount'),
